from copy import deepcopy
import unittest

from workflow import api, atomic_pointer_updates


class AtomicPointerUpdatesTests(unittest.TestCase):
    def implementations(self):
        return (atomic_pointer_updates.apply_updates, api.apply_updates)

    def test_decoding_and_empty_keys(self):
        for apply in self.implementations():
            with self.subTest(apply=apply):
                document = {\"a/b\": {\"~key\": 1}, \"\": {\"\": 2}, \"~1\": 3}
                result = apply(document, [(\"/a~1b/~0key\", 4), (\"//\", 5),
                                          (\"/~01\", 6)])
                self.assertEqual(result, {\"a/b\": {\"~key\": 4}, \"\": {\"\": 5}, \"~1\": 6})

    def test_missing_paths_fail_atomically(self):
        for apply in self.implementations():
            for pointer in (\"/missing\", \"/missing/key\", \"/scalar/key\", \"/items/0\"):
                with self.subTest(apply=apply, pointer=pointer):
                    document = {\"ok\": {\"value\": 1}, \"scalar\": 2, \"items\": []}
                    value = {\"nested\": []}
                    before = deepcopy(document)
                    with self.assertRaises(KeyError):
                        apply(document, [(\"/ok\", value), (pointer, 9)])
                    self.assertEqual(document, before)
                    self.assertEqual(value, {\"nested\": []})

    def test_invalid_pointers_fail_atomically(self):
        for apply in self.implementations():
            for pointer in (\"key\", \"~1key\", \"/~\", \"/~2\", \"/a~01/~x\"):
                with self.subTest(apply=apply, pointer=pointer):
                    document = {\"key\": 1}
                    with self.assertRaises(ValueError):
                        apply(document, [(\"/key\", 2), (pointer, 3)])
                    self.assertEqual(document, {\"key\": 1})

    def test_replacements_are_detached_and_sequential(self):
        for apply in self.implementations():
            with self.subTest(apply=apply):
                document = {\"target\": None, \"untouched\": []}
                value = {\"child\": []}
                result = apply(document, [(\"/target\", value), (\"/target/child\", [1])])
                self.assertEqual(value, {\"child\": []})
                result[\"untouched\"].append(2)
                result[\"target\"][\"child\"].append(3)
                self.assertEqual(document, {\"target\": None, \"untouched\": []})
                self.assertEqual(value, {\"child\": []})
                replacement = {\"child\": []}
                result = apply(document, [(\"/target\", replacement)])
                replacement[\"child\"].append(4)
                self.assertEqual(result[\"target\"], {\"child\": []})

    def test_root_replacement_and_no_updates_are_detached(self):
        for apply in self.implementations():
            with self.subTest(apply=apply):
                document = {\"child\": []}
                result = apply(document, [])
                result[\"child\"].append(1)
                self.assertEqual(document, {\"child\": []})
                replacement = {\"child\": []}
                result = apply(document, [(\"\", replacement), (\"/child\", [2])])
                self.assertEqual(result, {\"child\": [2]})
                self.assertEqual(replacement, {\"child\": []})
                result = apply(document, [(\"\", replacement)])
                result[\"child\"].append(3)
                self.assertEqual(replacement, {\"child\": []})
                self.assertEqual(apply(document, [(\"\", 7)]), 7)
EOF
